/* Apps web: instala y ejecuta programas HTML (HTML, CSS y formularios con calculos) */
#include "../web/kernel.h"
#include "font8x16.h"
int z_http_get(const char *, char **, long *, char *, int, int *);
static zwin *G;
void strlcpy(char *d, const char *s, size_t n) { strncpy0(d, s, n); }
void gfx_fill(int x, int y, int w, int h, u32 c) { g_rect(G, x, y, w, h, c & 0xFFFFFF); }
void gfx_char(int x, int y, u8 c, u32 k) { g_glyph(G, x, y, c, k & 0xFFFFFF); }
void gfx_text_big(int x, int y, const char *s, u32 k, int sc) { for (; *s; s++, x += 8 * sc) { const u8 *g = font8x16 + (u8)*s * 16; for (int j = 0; j < 16; j++) for (int i = 0; i < 8; i++) if (g[j] & (0x80 >> i)) g_rect(G, x + i * sc, y + j * sc, sc, sc, k & 0xFFFFFF); } }
void gfx_image(int x, int y, int w, int h, const u32 *px, int iw, int ih) { for (int j = 0; j < h; j++) { const u32 *r = px + (long)j * ih / h * iw; for (int i = 0; i < w; i++) g_rect(G, x + i, y + j, 1, 1, r[(long)i * iw / w] & 0xFFFFFF); } }
const char *clip_get(int *l) { static char b[4096]; *l = z_clip_get(b, 4095); b[*l] = 0; return b; }
void clip_set(const char *s, int n) { z_clip_set(s, n); }
#define TB 32
/* --- visor --- */
static int viewer(const char *path) {
    char cur[320], hist[16][320]; int nh = 0; strncpy0(cur, path, 320); zsys s; z_sysinfo(&s); G = zw_new("Programa", -1, 0, MIN(820, (int)s.scr_w - 60), MIN(600, (int)s.scr_h - 100), WF_DECOR | WF_RESIZE); zwin *w = G; struct html_doc *d = 0; char *src = 0; long n = 0; int scroll = 0;
reload: if (d) html_free(d); free(src); d = 0; src = z_readfile(cur, &n); if (!src) { src = strdup("<h1>No se puede abrir</h1>"); n = strlen(src); } d = html_load(src, n, w->w - 10); scroll = 0; { const char *t = html_title(d); zw_title(w->id, t && *t ? t : "Programa"); char m[120]; snprintf(m, 120, "[prueba] app web abierta: alto %d, script %d", html_height(d), html_has_script(d)); z_log(m); }
    zevent e;
    for (;;) { int vh = w->h - TB, mx = MAX(0, html_height(d) - vh); scroll = MAX(0, MIN(scroll, mx)); g_rect(w, 0, TB, w->w, vh, html_background(d) & 0xFFFFFF); zw_clip(w, 0, TB, w->w - 8, vh); html_draw(d, 0, TB, w->w - 10, vh, scroll); zw_noclip(w); g_rect(w, 0, 0, w->w, TB, UI_PANEL); ui_button(w, 4, 3, 30, 26, "<", 0); ui_button(w, 38, 3, 30, 26, "R", 0); if (html_has_script(d)) g_text(w, 78, 8, "Este programa usa JavaScript: aqui solo funciona su contenido y sus formularios.", 0xB45309); if (mx) { int bh = MAX(24, vh * vh / html_height(d)); g_rect(w, w->w - 7, TB + scroll * (vh - bh) / mx, 5, bh, UI_LINE); } zw_present(w); int go = 0; while (!go) { if (!z_event(&e, -1) || e.win != (u32)w->id) continue; if (e.type == EV_CLOSE) return 0; if (e.type == EV_RESIZE) { zw_resized(w, e.x, e.y); goto reload; } if (e.type == EV_WHEEL) { scroll -= (int)e.key * 48; go = 1; } else if (e.type == EV_DOWN) { go = 1; if (e.y < TB) { if (e.x < 36) { if (nh) { strcpy(cur, hist[--nh]); goto reload; } } else if (e.x < 70) goto reload; break; } int X = e.x, Y = e.y - TB + scroll; if (html_click_n(d, X, Y, ui_clicks(&e))) { html_relayout(d); break; } const char *l = html_link_at(d, X, Y); if (l) { if (l[0] == '#') { int a = html_anchor_y(d, l + 1); if (a >= 0) scroll = a; } else if (!strncmp(l, "http://", 7) || !strncmp(l, "https://", 8)) z_spawn("/rd/bin/browser", l); else { char nx[320]; strcpy(nx, cur); char *sl = strrchr(nx, '/'); if (sl) strncpy0(sl + 1, l, 320 - (sl + 1 - nx)); char *h = strchr(nx, '#'); if (h) *h = 0; if (nh < 16) strcpy(hist[nh++], cur); strcpy(cur, nx); goto reload; } } } else if (e.type == EV_KEY) { go = 1; int k = e.key == K_UP ? KEY_UP : e.key == K_DOWN ? KEY_DOWN : e.key == K_LEFT ? KEY_LEFT : e.key == K_RIGHT ? KEY_RIGHT : e.key == K_HOME ? KEY_HOME : e.key == K_END ? KEY_END : e.key == K_PGUP ? KEY_PGUP : e.key == K_PGDN ? KEY_PGDN : e.key == K_DEL ? KEY_DEL : e.ch < 128 ? (int)e.ch : uni_to_cp437(e.ch); if (k && html_key(d, k)) { html_relayout(d); int f = html_focus_y(d); if (f >= 0) { if (f < scroll) scroll = f - 20; if (f > scroll + vh - 40) scroll = f - vh + 60; } } else if (e.key == K_DOWN) scroll += 40; else if (e.key == K_UP) scroll -= 40; else if (e.key == K_PGDN || e.ch == ' ') scroll += vh - 30; else if (e.key == K_PGUP) scroll -= vh - 30; else if (e.key == K_HOME) scroll = 0; else if (e.key == K_END) scroll = mx; } } }
}
/* --- gestor --- */
typedef struct { char name[120]; char path[260]; long size; } pr_t;
static zwin *W; static pr_t *L; static int n, sel = -1, top, tab, ptop; static pr_t *F; static int nf; static char dirp[80], msg[160]; static char url[256] = "http://", *paste; static int pl, ufoc, ucur = 7, nfoc; static char pname[64] = "Mi programa"; static int ncur = 11;
static int cmp(const void *a, const void *b) { return strcasecmp(((pr_t *)a)->name, ((pr_t *)b)->name); }
static void strip(char *s) { char *d = strrchr(s, '.'); if (d) *d = 0; }
static void load(void) { n = 0; zdirent d; for (int i = 0; n < 500 && !z_readdir(dirp, i, &d); i++) if (!d.is_dir && (z_ends(d.name, ".html") || z_ends(d.name, ".htm"))) { strncpy0(L[n].name, d.name, 120); strip(L[n].name); snprintf(L[n].path, 260, "%s/%s", dirp, d.name); L[n].size = d.size; n++; } qsort(L, n, sizeof *L, cmp); if (sel >= n) sel = -1; }
static void scan(const char *p, int depth) { if (depth > 5 || nf >= 500) return; zdirent d; char q[260]; for (int i = 0; nf < 500 && !z_readdir(p, i, &d); i++) { snprintf(q, 260, "%s/%s", p, d.name); if (d.is_dir) { if (strcmp(q, dirp) && d.name[0] != '.' && strcasecmp(d.name, "Windows")) scan(q, depth + 1); } else if (z_ends(d.name, ".html") || z_ends(d.name, ".htm")) { strncpy0(F[nf].name, d.name, 120); strncpy0(F[nf].path, q, 260); F[nf].size = d.size; nf++; } } }
static void find_all(void) { nf = 0; zmount m[32]; int c = z_mounts(m, 32); for (int i = 0; i < c; i++) { if (!strcmp(m[i].name, "rd")) continue; char p[24]; snprintf(p, 24, "/%s", m[i].name); snprintf(msg, 160, _("Buscando en %s..."), p); scan(p, 0); } qsort(F, nf, sizeof *F, cmp); snprintf(msg, 160, _("%d archivos HTML encontrados"), nf); }
static void safe(const char *s, char *o, int c) { int k = 0; for (; *s && k < c - 1; s++) o[k++] = strchr("/\\:*?\"<>|", *s) ? '_' : *s; o[k] = 0; }
static int install(const char *name, const char *d, long l) { char s[100], p[260]; safe(name, s, 90); if (!s[0]) strcpy(s, "programa"); snprintf(p, 260, "%s/%s%s", dirp, s, z_ends(s, ".html") ? "" : ".html"); int e = z_writefile(p, d, l); snprintf(msg, 160, e ? "Error: %s" : _("Instalado: %s"), e ? z_errstr(e) : s); char m[200]; snprintf(m, 200, "[prueba] app instalada %s: %s", s, e ? z_errstr(e) : "OK"); z_log(m); load(); return e; }
static const char *T[] = {"Instalados", "Desde archivo", "Pegar HTML", "Desde internet"};
static void draw(void) { g_clear(W, UI_WHITE); g_rect(W, 0, 0, W->w, 36, UI_PANEL); for (int i = 0; i < 4; i++) ui_button(W, 6 + i * 126, 5, 122, 26, T[i], tab == i ? 2 : 0); int y = 44, h = W->h - 96; if (tab < 2) { pr_t *l = tab ? F : L; int c = tab ? nf : n, vis = h / 24, *t = tab ? &ptop : &top; for (int i = *t; i < c && i < *t + vis; i++) { int Y = y + (i - *t) * 24; if (i == sel) g_rect(W, 0, Y, W->w, 24, UI_ACC2); g_round(W, 10, Y + 3, 18, 18, 3, UI_ACC); zw_clip(W, 36, Y, W->w - 120, 24); g_text(W, 36, Y + 4, tab ? l[i].path : l[i].name, UI_TEXT); zw_noclip(W); char s[20]; snprintf(s, 20, "%ld KB", (l[i].size + 1023) / 1024); g_text(W, W->w - 12 - g_textw(s), Y + 4, s, UI_MUTED); } if (!c) g_text(W, 14, y + 10, tab ? "Pulsa Buscar para explorar todas las unidades." : "Aun no hay programas. Instala alguno desde las otras pestanas.", UI_MUTED); } else if (tab == 2) { g_text(W, 14, y + 4, "Nombre", UI_TEXT); ui_input(W, 80, y, 300, 26, pname, ncur, nfoc); g_text(W, 14, y + 38, "Copia el codigo HTML en otra ventana y pulsa Ctrl+V aqui.", UI_MUTED); g_rect(W, 14, y + 60, W->w - 28, h - 70, UI_BG); g_frame(W, 14, y + 60, W->w - 28, h - 70, UI_LINE); char s[60]; snprintf(s, 60, _("%d bytes pegados"), pl); g_text(W, 22, y + 68, s, UI_TEXT); if (paste) { zw_clip(W, 16, y + 90, W->w - 32, h - 102); int Y = y + 92; const char *p = paste; char ln[120]; for (int r = 0; r < 14 && *p; r++) { int k = 0; while (*p && *p != '\n' && k < 118) ln[k++] = *p++; while (*p && *p != '\n') p++; if (*p) p++; ln[k] = 0; g_text(W, 20, Y, ln, UI_MUTED); Y += 16; } zw_noclip(W); } } else { g_text(W, 14, y + 4, "Direccion http://", UI_TEXT); ui_input(W, 14, y + 26, W->w - 28, 26, url, ucur, ufoc); g_text(W, 14, y + 62, "Admite http:// y https://.", UI_MUTED); } g_rect(W, 0, W->h - 46, W->w, 46, UI_PANEL); g_text(W, 12, W->h - 32, msg, UI_TEXT); static const char *B[] = {"Abrir", "Instalar", "Instalar", "Descargar"}; ui_button(W, W->w - 108, W->h - 38, 96, 30, B[tab], 2); if (tab == 0) ui_button(W, W->w - 212, W->h - 38, 96, 30, "Borrar", 0); if (tab == 1) ui_button(W, W->w - 212, W->h - 38, 96, 30, "Buscar", 0); zw_present(W); }
static void act(void) { if (tab == 0 && sel >= 0) z_spawn("/rd/bin/apps", L[sel].path); else if (tab == 1 && sel >= 0) { long l; char *d = z_readfile(F[sel].path, &l); if (d) { install(F[sel].name, d, l); free(d); } } else if (tab == 2 && pl) install(pname, paste, pl); else if (tab == 3) { char *b; long l; int st = 0; strcpy(msg, _("Descargando...")); draw(); int e = z_http_get(url, &b, &l, 0, 0, &st); if (e <= -1000) snprintf(msg, 160, "%s", z_http_err(e)); else if (e || st != 200) snprintf(msg, 160, "Error: %s (HTTP %d)", e ? z_errstr(e) : "respuesta", st); else { char nm[100]; const char *q = strrchr(url + 7, '/'); strncpy0(nm, q && q[1] ? q + 1 : "pagina", 100); char *x = strchr(nm, '?'); if (x) *x = 0; install(nm, b, l); free(b); } } }
int main(const char *a) { if (a[0]) return viewer(a); zdirent st; strcpy(dirp, z_stat("/sys", &st) ? "/rd/tmp/PROGRAMAS" : "/sys/PROGRAMAS"); z_mkdir(dirp); L = malloc(500 * sizeof *L); F = malloc(500 * sizeof *F); paste = calloc(1, 65537); load(); G = W = zw_new("Apps web", -1, 0, 720, 480, WF_DECOR | WF_RESIZE); snprintf(msg, 160, _("%d programas instalados en %s"), n, dirp); draw(); zevent e; u64 lc = 0; int li = -1;
    for (;;) { if (!z_event(&e, -1) || e.win != (u32)W->id) continue; if (e.type == EV_REDRAW) { draw(); continue; } if (e.type == EV_CLOSE) return 0; if (e.type == EV_RESIZE) zw_resized(W, e.x, e.y); else if (e.type == EV_WHEEL) { int *t = tab ? &ptop : &top; *t = MAX(0, *t - (int)e.key * 3); } else if (e.type == EV_KEY) { if (tab == 2) { if (e.ch == 22 && !nfoc) { pl = z_clip_get(paste, 65536); paste[pl] = 0; strcpy(msg, _("Codigo pegado. Pulsa Instalar.")); } else if (nfoc) ui_input_key(pname, 60, &ncur, &e); } else if (tab == 3) { if (e.ch == '\n') act(); else ui_input_key(url, 250, &ucur, &e); } else if (e.key == K_DOWN) sel = MIN(sel + 1, (tab ? nf : n) - 1); else if (e.key == K_UP) sel = MAX(sel - 1, 0); else if (e.ch == '\n') act(); } else if (e.type == EV_DOWN) { if (e.y < 36) { int t = (e.x - 6) / 126; if (t >= 0 && t < 4) { tab = t; sel = -1; msg[0] = 0; ufoc = t == 3; if (t == 1 && !nf) { draw(); find_all(); } } } else if (e.y >= W->h - 46) { if (e.x >= W->w - 108) act(); else if (e.x >= W->w - 212) { if (tab == 0 && sel >= 0) { char q[160]; snprintf(q, 160, _("Borrar %.80s?"), L[sel].name); if (ui_confirm("Borrar programa", q)) { z_unlink(L[sel].path); z_sync(); load(); } } else if (tab == 1) find_all(); } } else if (tab < 2) { int i = (tab ? ptop : top) + (e.y - 44) / 24; if (i < (tab ? nf : n) && e.y >= 44 && tab == 0 && (e.btn & 2)) { sel = i; draw(); static const char *it[] = {"Abrir", "Desinstalar"}; int sx, sy; zw_screen(W, e.x, e.y, &sx, &sy); int r = ui_menu(sx, sy, it, 2); if (r == 0) act(); else if (r == 1) { char q[160]; snprintf(q, 160, "%s %.80s?", _("¿Desinstalar"), L[sel].name); if (ui_confirm("Desinstalar", q)) { int er = z_trash(L[sel].path); if (er) er = z_unlink(L[sel].path); z_sync(); load(); snprintf(msg, 160, "%s", er ? z_errstr(er) : _("Desinstalado (está en la papelera)")); z_log("[prueba] app web desinstalada"); } } } else if (i < (tab ? nf : n) && e.y >= 44) { u64 t = z_ms(); if (i == li && t - lc < 500) { sel = i; act(); li = -1; } else { sel = i; li = i; lc = t; } } } else if (tab == 2) { nfoc = e.y >= 44 && e.y < 70; if (nfoc) ui_input_click(W, &e, pname, &ncur); }; } else continue; draw(); }
}
